{
  "similarities": [
    {
      "point": "Both describe the ovolo as a convex architectural moulding.",
      "quote_britannica": "OVOLLO, or Ouvus, in architecture, a round moulding, whole profile, or sweep, in the ionic and compacite capittals, is usually a quadrant of a circle;",
      "quote_wikipedia": "The ovolo or echinus is a convex decorative molding profile used in architectural ornamentation."
    },
    {
      "point": "Both state the profile is usually a quarter of a circle.",
      "quote_britannica": "is usually a quadrant of a circle; whence it is also commonly called the quartercard.",
      "quote_wikipedia": "Its profile is a quarter to a half of a more or less flattened circle."
    },
    {
      "point": "Both mention the egg-and-anchor ornamentation.",
      "quote_britannica": "It is mainly cut with the reproduction of eggs and anchors or arrows heads placed alternately.",
      "quote_wikipedia": "The \"egg and tongue\" referred to, also known as egg-and-dart, egg-and-anchor, or egg-and-star, refers to alternating egg and V-shapes enriching the surface of the concave ovolo in many early cases."
    },
    {
      "point": "Both associate the moulding with Ionic capitals.",
      "quote_britannica": "in the ionic and compacite capittals, is usually a quadrant of a circle;",
      "quote_wikipedia": "Ovolo adornment by the egg-and-dart element was used on Ionic capitals by ancient Roman and ancient Greek builders"
    }
  ],
  "differences": [
    {
      "point": "Britannica calls it a round moulding, while Wikipedia calls it a convex decorative molding profile.",
      "quote_britannica": "OVOLLO, or Ouvus, in architecture, a round moulding, whole profile, or sweep, in the ionic and compacite capittals, is usually a quadrant of a circle;",
      "quote_wikipedia": "The ovolo or echinus is a convex decorative molding profile used in architectural ornamentation."
    },
    {
      "point": "Britannica says the profile is usually a quadrant of a circle, while Wikipedia says it is a quarter to a half of a flattened circle.",
      "quote_britannica": "is usually a quadrant of a circle; whence it is also commonly called the quartercard.",
      "quote_wikipedia": "Its profile is a quarter to a half of a more or less flattened circle."
    },
    {
      "point": "Britannica describes the ovolo surface as concave in the ornamentation context, while Wikipedia describes the ovolo itself as convex.",
      "quote_britannica": "It is mainly cut with the reproduction of eggs and anchors or arrows heads placed alternately.",
      "quote_wikipedia": "enriching the surface of the concave ovolo in many early cases."
    },
    {
      "point": "Britannica includes an unrelated river entry, while Wikipedia does not.",
      "quote_britannica": "Ouss, a river, which, riding in the north of Yorkshire, runs fourth-rail by York; and, combining that course, falls into the Trent.",
      "quote_wikipedia": "Ovolo is an Italian word that means \"little egg\"."
    }
  ],
  "claims": [
    {
      "claim": "The ovolo is also called Ouvus.",
      "tag": "dropped",
      "quote_britannica": "OVOLLO, or Ouvus, in architecture, a round moulding, whole profile, or sweep, in the ionic and compacite capittals, is usually a quadrant of a circle;",
      "quote_wikipedia": null
